class Solution:
    def resultArray(self, nums: List[int], k: int) -> List[int]:
        result = [0] * k
        ending = [0] * k                         # ending[r]: subarrays ending at the previous index with product % k == r
        for a in nums:
            nxt = [0] * k
            nxt[a % k] += 1                      # the subarray [a] on its own
            for r in range(k):                   # extend every earlier subarray by a
                nxt[(r * a) % k] += ending[r]
            ending = nxt
            for r in range(k):
                result[r] += ending[r]
        return result
